  static class StudentApps {
    const string Student="LEV VIGOTSKY";
    static readonly string[] Essential={"system","idle","registry","smss","csrss","wininit","winlogon","logonui","services","lsass","svchost","fontdrvhost","dwm","explorer","sihost","taskhostw","ctfmon","conhost","dllhost","runtimebroker","shellexperiencehost","startmenuexperiencehost","searchhost","searchapp","textinputhost","applicationframehost","securityhealthsystray","securityhealthservice","widgets","widgetservice","userinit","rdpclip","audiodg","wudfhost","msedgewebview2"};
    [StructLayout(LayoutKind.Sequential)]struct WtsSession {public int SessionID;public IntPtr Station;public int State;}
    [DllImport("wtsapi32.dll",SetLastError=true)]static extern bool WTSEnumerateSessions(IntPtr server,int reserved,int version,out IntPtr sessions,out int count);
    [DllImport("wtsapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool WTSQuerySessionInformation(IntPtr server,int session,int infoClass,out IntPtr buffer,out int bytes);
    [DllImport("wtsapi32.dll")]static extern void WTSFreeMemory(IntPtr buffer);
    static Dictionary<int,string> Sessions(){var result=new Dictionary<int,string>();IntPtr data;int count;if(!WTSEnumerateSessions(IntPtr.Zero,0,1,out data,out count))throw new Exception("Could not enumerate logged-in sessions; no apps were closed");try{int size=Marshal.SizeOf(typeof(WtsSession));for(int i=0;i<count;i++){var s=(WtsSession)Marshal.PtrToStructure(IntPtr.Add(data,i*size),typeof(WtsSession));IntPtr p;int bytes;if(WTSQuerySessionInformation(IntPtr.Zero,s.SessionID,5,out p,out bytes)){try{string user=Marshal.PtrToStringUni(p);if(s.SessionID>0&&string.Equals(user,Student,StringComparison.OrdinalIgnoreCase))result[s.SessionID]=user;}finally{WTSFreeMemory(p);}}}}finally{WTSFreeMemory(data);}return result;}
    [DllImport("wtsapi32.dll",SetLastError=true)]static extern bool WTSLogoffSession(IntPtr server,int session,bool wait);
    public static void SignOutStudent(){foreach(var entry in Sessions()){
      IntPtr buffer;int bytes;if(!WTSQuerySessionInformation(IntPtr.Zero,entry.Key,7,out buffer,out bytes))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
      string domain;try{domain=Marshal.PtrToStringUni(buffer);}finally{WTSFreeMemory(buffer);}
      if(!string.Equals(domain,Environment.MachineName,StringComparison.OrdinalIgnoreCase))throw new Exception("Student session domain could not be verified; no session was signed out");
      if(!WTSLogoffSession(IntPtr.Zero,entry.Key,true))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
    }}
