    public static bool SafeToClose(string processName,string fullPath,string owner,string sessionUser,int sessionId){
      if(sessionId<=0||!string.Equals(owner,Student,StringComparison.OrdinalIgnoreCase)||!string.Equals(sessionUser,Student,StringComparison.OrdinalIgnoreCase)||string.IsNullOrEmpty(fullPath))return false;
      string name=(processName??"").ToLowerInvariant();foreach(string files in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)}){if(string.IsNullOrEmpty(files))continue;if(fullPath.StartsWith(Path.Combine(files,"Veyon")+"\\",StringComparison.OrdinalIgnoreCase)||fullPath.StartsWith(Path.Combine(files,"UEPLV")+"\\",StringComparison.OrdinalIgnoreCase))return false;if(Essential.Contains(name)&&(fullPath.StartsWith(Path.Combine(files,"WindowsApps")+"\\",StringComparison.OrdinalIgnoreCase)||fullPath.StartsWith(Path.Combine(files,@"Microsoft\EdgeWebView")+"\\",StringComparison.OrdinalIgnoreCase)))return false;}
