      foreach(var p in candidates){try{string sessionUser;if(p.HasExited)continue;if(!sessions.TryGetValue(p.SessionId,out sessionUser)||OwnerSid(p.Id)!=localSid||!(SafeToClose(p.ProcessName,p.MainModule.FileName,Owner(p.Id),sessionUser,p.SessionId)||(closeTaskManager&&SafeToCloseTaskManager(p.ProcessName,p.MainModule.FileName,Owner(p.Id),sessionUser,p.SessionId)))){protectedCount++;continue;}bool requested=p.CloseMainWindow();if(requested&&p.WaitForExit(2000)){closed++;continue;}if(!p.HasExited){p.Kill();if(!p.WaitForExit(3000)){failed++;continue;}}closed++;}catch{failed++;}finally{p.Dispose();}}
      string detail="Closed "+closed+" student application processes; "+failed+" could not close. Windows, Veyon, management and staff processes were preserved ("+protectedCount+" protected/skipped). Unsaved student work may be lost.";if(failed>0)throw new Exception(detail);return detail;
    }
  }
