      string raw;using(var response=req.GetResponse()){if(response.ContentLength>1048576)throw new Exception("Management response too large");using(var reader=new StreamReader(response.GetResponseStream())){var buffer=new char[1048577];int count=0,n;while(count<buffer.Length&&(n=reader.Read(buffer,count,buffer.Length-count))>0)count+=n;if(count>1048576)throw new Exception("Management response too large");raw=new string(buffer,0,count);}}
