    }
    void CheckRelease(ReleaseDescriptor descriptor){if(descriptor==null)return;try{
      string key=LoadPinnedReleaseKey();var manifest=Util.VerifyReleaseManifest(descriptor.manifestJson,descriptor.signature,key);if(manifest.version!=descriptor.version||!string.Equals(manifest.packageSha256,descriptor.packageSha256,StringComparison.OrdinalIgnoreCase))throw new Exception("Release descriptor does not match the signed manifest");
      state.availableUpdateVersion=manifest.version;Save();var c=ReadCoordinator();if(c.requiresStaffReview||Util.ReleaseVersion(manifest.version)<=Util.ReleaseVersion(c.installedVersion)||c.failedVersion==manifest.version)return;
      if(!new[]{"idle","complete","failed","rejected"}.Contains(c.phase))return;
      string pending=Path.Combine(UpdateDirectory(),"pending-package.json");if(!Util.PrivateUpdateFile(pending))throw new Exception("Automatic updater's private precreated cache is missing or has unsafe permissions");
      bool cacheValid=false;try{var cached=Util.From<PendingRelease>(File.ReadAllText(pending));if(cached!=null&&cached.manifestJson==descriptor.manifestJson&&cached.signature==descriptor.signature){Util.VerifyReleasePackage(manifest,cached.packageBase64);state.downloadedUpdateUtc=cached.downloadedUtc;cacheValid=true;}}catch{}if(cacheValid){state.updateLastError=null;Save();TriggerUpdateTask();return;}
      var request=new UpdateRequest{requestId=Guid.NewGuid().ToString(),sentUtc=Util.Utc(),deviceId=state.deviceId,version=manifest.version};string endpoint=new Uri(new Uri(cfg.cloudUrl),"/api/agent/update").AbsoluteUri;
      var reply=Util.From<UpdateReply>(HttpExchange(endpoint,cfg.cloudKey,request,true));if(reply==null||reply.requestId!=request.requestId||!Util.Fresh(reply.serverUtc,120)||!reply.accepted||reply.update==null)throw new Exception("Cloud release download was not accepted or bound to its request");
      if(reply.update.manifestJson!=descriptor.manifestJson||reply.update.signature!=descriptor.signature)throw new Exception("Downloaded release differs from the advertised signed release");
      var downloaded=Util.VerifyReleaseManifest(reply.update.manifestJson,reply.update.signature,key);Util.VerifyReleasePackage(downloaded,reply.update.packageBase64);reply.update.downloadedUtc=Util.Utc();var bytes=Encoding.UTF8.GetBytes(Util.Json(reply.update));
      using(var f=new FileStream(pending,FileMode.Open,FileAccess.Write,FileShare.None)){f.Position=0;f.Write(bytes,0,bytes.Length);f.SetLength(bytes.Length);f.Flush(true);}
