    }catch(Exception ex){state.updateLastError=ex is WebException?"Signed update download is unavailable":ex.Message;Save();}}
    void TriggerUpdateTask(){Util.Run(Path.Combine(Environment.SystemDirectory,"schtasks.exe"),"/Run /TN UEPLV-AutomaticUpdate",10000);}
    static long BootTicks(){try{using(var q=new ManagementObjectSearcher("SELECT LastBootUpTime FROM Win32_OperatingSystem")){foreach(ManagementObject o in q.Get())return ManagementDateTimeConverter.ToDateTime((string)o["LastBootUpTime"]).ToUniversalTime().Ticks;}}catch{}return 0;}
    Status Snapshot(){var s=new Status{freezeLease=state.freezeLease,session=SessionTransitions.Public(state.session),name=cfg.name,utc=Util.Utc(),mode=mode,modeApplied=state.policiesApplied&&privacyReady&&ChatSupport.Ready,policyError=state.policyError,activeAction=state.activeAction,maintenanceBlocked=state.maintenanceBlocked,maintenanceBlockReason=state.maintenanceBlockReason,bootTicks=BootTicks(),cloudConfigured=!string.IsNullOrEmpty(cfg.cloudUrl),cloudLastSuccessUtc=state.cloudLastSuccessUtc,cloudLastError=state.cloudLastError,update=UpdateStatus()};string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"UEPLV");
      try{var d=Util.From<DeploymentReport>(File.ReadAllText(Path.Combine(root,"Reports","deployment.json")));s.installation=new DeploymentSnapshot{stage=d.Success?"Provisioned-awaiting-protection":"Provisioning-failed",success=d.Success?(bool?)null:false,detail=d.Error??d.Protection,utc=d.CompletedUtc};}catch{}
      try{var f=Util.From<FinalizationReport>(File.ReadAllText(Path.Combine(root,"finalization-state.json")));s.installation=new DeploymentSnapshot{stage=f.Stage,success=!string.IsNullOrEmpty(f.Failure)?(bool?)false:(f.Complete?(bool?)true:null),detail=f.Failure,utc=f.LastRunUtc};}catch{}
      try{using(var q=new ManagementObjectSearcher("SELECT InstallState FROM Win32_OptionalFeature WHERE Name='Client-UnifiedWriteFilter'")){foreach(ManagementObject o in q.Get()){int value=Convert.ToInt32(o["InstallState"]);s.uwfFeatureEnabled=value==1?(bool?)true:(value==2||value==3)?(bool?)false:null;}}}catch{}
      try{
      using(var q=new ManagementObjectSearcher(@"root\standardcimv2\embedded","SELECT * FROM UWF_Filter")){foreach(ManagementObject o in q.Get()){s.currentEnabled=Convert.ToBoolean(o["CurrentEnabled"]);s.nextEnabled=Convert.ToBoolean(o["NextEnabled"]);}}
      using(var q=new ManagementObjectSearcher(@"root\standardcimv2\embedded","SELECT * FROM UWF_Volume WHERE DriveLetter = 'C:'")){foreach(ManagementObject o in q.Get()){if(Convert.ToBoolean(o["CurrentSession"]))s.currentCProtected=Convert.ToBoolean(o["Protected"]);else s.nextCProtected=Convert.ToBoolean(o["Protected"]);}}
      using(var q=new ManagementObjectSearcher(@"root\standardcimv2\embedded","SELECT * FROM UWF_Servicing")){foreach(ManagementObject o in q.Get()){if(Convert.ToBoolean(o["CurrentSession"]))s.currentServicing=Convert.ToBoolean(o["ServicingEnabled"]);else s.nextServicing=Convert.ToBoolean(o["ServicingEnabled"]);}}
      using(var q=new ManagementObjectSearcher(@"root\standardcimv2\embedded","SELECT * FROM UWF_Overlay")){foreach(ManagementObject o in q.Get()){s.overlayMB=Convert.ToUInt32(o["OverlayConsumption"]);s.availableMB=Convert.ToUInt32(o["AvailableSpace"]);s.overlayWarningMB=Convert.ToUInt32(o["WarningOverlayThreshold"]);s.overlayCriticalMB=Convert.ToUInt32(o["CriticalOverlayThreshold"]);}}
    }catch(ManagementException ex){s.uwfError="UWF provider unavailable: "+ex.ErrorCode;}catch{s.uwfError="UWF status could not be read";}return s;}
    string Discover(){using(var udp=new UdpClient()){udp.EnableBroadcast=true;udp.Client.ReceiveTimeout=2500;var d=new Discovery{name=cfg.name,nonce=Util.Token(24)};var b=Encoding.UTF8.GetBytes(Util.Json(d));udp.Send(b,b.Length,new IPEndPoint(IPAddress.Broadcast,cfg.discoveryPort));for(int i=0;i<5;i++){try{var remote=new IPEndPoint(IPAddress.Any,0);var reply=Util.From<Discovery>(Encoding.UTF8.GetString(udp.Receive(ref remote)));if(reply.name==d.name&&reply.nonce==d.nonce&&reply.port==cfg.gatewayPort&&Util.Verify(cfg.discoveryPublicKey,reply.name+"\n"+reply.nonce+"\n"+reply.port,reply.signature))return remote.Address.ToString();}catch(SocketException){break;}catch{}}}return null;}
    void RefreshRestartResults(Status status){lock(gate){foreach(var r in state.results.Where(x=>(x.state=="awaiting-restart"||x.state=="shutdown-scheduled")&&x.action!="freeze-reboot"&&x.action!="thaw-reboot").ToArray()){if(status.bootTicks!=0&&status.bootTicks!=r.bootTicks){if(r.action=="maintenance"&&status.currentServicing==true)continue;bool ok=r.action=="uwf-reset-stage1"?status.uwfFeatureEnabled==false:r.action=="uwf-reset-stage2"?status.uwfFeatureEnabled==true:r.action=="uwf-enable"?Util.ProtectionConsistent(status):r.action=="uwf-disable"?(status.currentEnabled==false&&status.nextEnabled==false&&status.currentCProtected==false&&status.nextCProtected==false):r.action=="maintenance"?Util.ProtectionConsistent(status):true;r.state=!ok?"failed":r.action=="maintenance"?"needs-update-review":r.action=="windows-update"?"needs-update-check":r.action=="uwf-repair"?"needs-repair-check":"completed";r.detail=r.action=="shutdown"?"Apagado solicitado; nuevo inicio detectado.":!ok?"Restart observed, but requested UWF filter/volume state did not verify.":r.action=="maintenance"?"Restart observed; filter/volume protection checked. Windows update success requires update-history review.":r.action=="windows-update"?"Restart observed; run Windows Update again to verify no updates remain.":r.action=="uwf-repair"?"DISM restart verified; run Repair again to finish SFC and review its health result.":"Restart verified";r.utc=Util.Utc();}}}}
    void Exchange(string endpoint,string credential,bool cloud){
      var status=Snapshot();RefreshRestartResults(status);
      Poll p;lock(gate){state.sequence++;Save();p=new Poll{requestId=Guid.NewGuid().ToString(),sentUtc=Util.Utc(),deviceId=state.deviceId,sequence=state.sequence,status=status,results=state.results.TakeLastCompat(100).Select(x=>new JobResult{id=x.id,action=x.action,state=x.state,detail=x.detail,utc=x.utc,bootTicks=x.bootTicks}).ToList()};}
      var req=(HttpWebRequest)WebRequest.Create(endpoint);req.Method="POST";req.Timeout=10000;req.ReadWriteTimeout=10000;req.ContentType="application/json";req.UserAgent="UEPLV-Management/1.2";if(!cloud)req.Proxy=null;
      var data=Encoding.UTF8.GetBytes(Util.Protect(cfg.name,credential,Util.Json(p)));req.ContentLength=data.Length;using(var stream=req.GetRequestStream())stream.Write(data,0,data.Length);
      string raw;using(var response=req.GetResponse()){if(response.ContentLength>1048576)throw new Exception("Management response too large");using(var reader=new StreamReader(response.GetResponseStream())){var buffer=new char[1048577];int count=0,n;while(count<buffer.Length&&(n=reader.Read(buffer,count,buffer.Length-count))>0)count+=n;if(count>1048576)throw new Exception("Management response too large");raw=new string(buffer,0,count);}}
      var rep=Util.From<Reply>(Util.Unprotect(cfg.name,credential,raw));if(rep.requestId!=p.requestId||!Util.Fresh(rep.serverUtc,120)||!rep.accepted)throw new Exception("Management endpoint rejected enrollment or returned an invalid response");
      if(!state.enrolled){state.enrolled=true;state.enrollmentUtc=Util.Utc();}state.lastSuccessUtc=Util.Utc();if(cloud){state.cloudLastSuccessUtc=state.lastSuccessUtc;state.cloudLastError=null;}else state.lastError=null;Save();
      AcceptPolicy(rep.policy);QueueJobs(rep.jobs,status.bootTicks);
      if(cloud)CheckRelease(rep.update);
    }
    void AcceptPolicy(WebsitePolicy policy){if(policy==null)return;if(policy.revision<1)throw new Exception("Invalid website policy revision");foreach(var list in new[]{policy.classDomains,policy.examDomains,policy.aiDomains}){if(list==null||list.Length>90||list.Any(x=>x==null||x.Length>253||!System.Text.RegularExpressions.Regex.IsMatch(x,@"^([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$")))throw new Exception("Invalid website policy domains");}lock(gate){if(state.websitePolicy!=null&&policy.revision<=state.websitePolicy.revision)return;state.websitePolicy=policy;Save();}}
    void QueueJobs(IEnumerable<Job> jobs,long bootTicks){bool added=false;
      foreach(var j in jobs??new List<Job>()){if(stopping)break;lock(gate){if(!Util.ValidJob(j)||queuedIds.Contains(j.id)||state.results.Any(x=>x.id==j.id))continue;if(actions.Count>=20)continue;queuedIds.Add(j.id);state.results.Add(new JobResult{id=j.id,action=j.action,state="queued",detail="Authenticated action queued",utc=Util.Utc(),bootTicks=bootTicks});actions.Enqueue(j);added=true;Save();Monitor.PulseAll(gate);}}
      if(added)Interlocked.CompareExchange(ref cloudQueuedReportTicks,DateTime.UtcNow.AddSeconds(10).Ticks,0);
    }
    void PullCloudCommands(){
      CommandRequest request;lock(gate){request=new CommandRequest{requestId=Guid.NewGuid().ToString(),sentUtc=Util.Utc(),deviceId=state.deviceId,knownIds=state.results.TakeLastCompat(1000).Select(x=>x.id).ToList()};}
      string endpoint=new Uri(new Uri(cfg.cloudUrl),"/api/agent/commands").AbsoluteUri;
      var reply=Util.From<Reply>(HttpExchange(endpoint,cfg.cloudKey,request,true));
      if(reply==null||reply.requestId!=request.requestId||!Util.Fresh(reply.serverUtc,120)||!reply.accepted)throw new Exception("Cloud command response was not accepted or bound to its request");
      AcceptPolicy(reply.policy);if(reply.jobs!=null&&reply.jobs.Count>0)QueueJobs(reply.jobs,BootTicks());
    }
    void CloudLoop(){
      int pc;int.TryParse(cfg.name.Split('-').Last(),out pc);int failures=0,lastReported=0;
      DateTime nextHeartbeat=DateTime.UtcNow.AddSeconds((pc*7)%5),nextCommands=DateTime.UtcNow.AddSeconds(5),retryAfter=DateTime.MinValue;
      while(!stopping){
        if(!Util.HostMatchesEnrollment(cfg.name,Environment.MachineName)||DateTime.UtcNow<retryAfter){Thread.Sleep(200);continue;}
        try{
          bool network=false;int revision=Interlocked.CompareExchange(ref cloudRevision,0,0);long queued=Interlocked.Read(ref cloudQueuedReportTicks);
          if(DateTime.UtcNow>=nextHeartbeat||revision!=lastReported||(queued>0&&DateTime.UtcNow.Ticks>=queued)){
            Exchange(cfg.cloudUrl,cfg.cloudKey,true);lastReported=revision;nextHeartbeat=DateTime.UtcNow.AddSeconds(Util.CloudInterval(cfg));
            if(queued>0)Interlocked.CompareExchange(ref cloudQueuedReportTicks,0,queued);network=true;
          }
          if(!stopping&&DateTime.UtcNow>=nextCommands){PullCloudCommands();nextCommands=DateTime.UtcNow.AddSeconds(5);network=true;}
          if(network)failures=0;
        }catch(Exception ex){failures=Math.Min(4,failures+1);retryAfter=DateTime.UtcNow.AddSeconds(Math.Min(60,5*(1<<failures)));state.cloudLastError=ex is WebException?"Conexión HTTPS con el Servidor: "+((WebException)ex).Status:ex.Message;Save();}
        Thread.Sleep(200);
      }
    }
    public void Loop(){int misses=0;int pc=0;int.TryParse(cfg.name.Split('-').Last(),out pc);DateTime nextLocal=DateTime.UtcNow;actionWorker=new Thread(ActionLoop){IsBackground=true};actionWorker.Start();if(!string.IsNullOrEmpty(cfg.cloudUrl)){cloudWorker=new Thread(CloudLoop){IsBackground=true};cloudWorker.Start();}while(!stopping){
      if(!Util.HostMatchesEnrollment(cfg.name,Environment.MachineName)){state.lastError="Waiting for computer-name restart: "+cfg.name;Save();Thread.Sleep(1000);continue;}
      if(!privacyReady){
        if(Monitor.TryEnter(operationGate)){try{
          var check=Snapshot();
          if(check.bootTicks>0&&(check.uwfFeatureEnabled==false||(check.currentEnabled==false&&check.nextEnabled==false&&check.currentServicing==false&&check.nextServicing==false))){
            lock(gate){state.activeAction="browser-cleanup";Save();}
            StudentApps.SignOutStudent();RunAction("browser-cleanup");
            lock(gate){state.privacyCleanupCampaign=PrivacyCampaign;state.privacyCleanupBoot=check.bootTicks;state.privacyCleanupError=null;state.policyError=null;privacyReady=true;Save();}
          }
        }catch(Exception ex){lock(gate){state.privacyCleanupError=ex.Message;state.policyError="Limpieza de navegador pendiente: "+ex.Message;Save();}}
        finally{lock(gate){state.activeAction=null;Save();}Monitor.Exit(operationGate);}}
        if(!privacyReady){Thread.Sleep(1000);continue;}
      }
      if(privacyReady&&state.privacyFrozenCampaign!=PrivacyCampaign){
        if(Monitor.TryEnter(operationGate)){try{
          var privacy=Snapshot();
          if(Util.ProtectionConsistent(privacy)&&privacy.bootTicks>0&&privacy.bootTicks!=state.privacyCleanupBoot){lock(gate){state.privacyFrozenCampaign=PrivacyCampaign;Save();}}
          if(privacy.currentEnabled==false){
            StudentApps.SignOutStudent();
            var phase=privacy.update.phase;var stage=privacy.installation==null?"":privacy.installation.stage;
            if(phase=="complete"&&privacy.nextEnabled==false&&privacy.installation!=null&&privacy.installation.success==true&&!SessionTransitions.Active(state.session)&&DateTime.UtcNow>=privacyNextProtectCheck){
              privacyNextProtectCheck=DateTime.UtcNow.AddSeconds(30);RunAction("uwf-enable");privacy=Snapshot();
            }
            bool restartSafe=phase=="verifying-protection"||(phase=="complete"&&privacy.installation!=null&&privacy.installation.success==true)||((phase=="idle"||phase=="complete")&&(stage=="ProtectionPending"||stage=="PostBoot"));
            if(restartSafe&&privacy.nextEnabled==true&&privacy.nextCProtected==true&&state.privacyRestartBoot!=privacy.bootTicks){
              RunAction("browser-cleanup");lock(gate){state.privacyRestartBoot=privacy.bootTicks;Save();}
              Util.Run(Path.Combine(Environment.SystemDirectory,"shutdown.exe"),"/r /t 0 /c \"UEPLV: limpieza de navegador terminada; activando protección.\"",10000);
            }
          }
        }catch(Exception ex){lock(gate){state.privacyCleanupError=ex.Message;Save();}}
        finally{Monitor.Exit(operationGate);}}
      }
      if(SessionTransitions.Pending(state.session)&&Monitor.TryEnter(operationGate)){try{lock(gate){string oldPhase=state.session.phase;SessionTransitions.Tick(state,Snapshot(),Save);if(oldPhase!=state.session.phase)Interlocked.Increment(ref cloudRevision);}}finally{Monitor.Exit(operationGate);}}
      if(FreezeSchedule.Active(state.freezeLease)&&Monitor.TryEnter(operationGate)){try{lock(gate){string oldLease=Util.Json(state.freezeLease);FreezeSchedule.Tick(state,Snapshot(),Save,SetFreezeFilter,Snapshot);if(oldLease!=Util.Json(state.freezeLease))Interlocked.Increment(ref cloudRevision);}}finally{Monitor.Exit(operationGate);}}
      try{CheckDailyShutdown();}catch(Exception ex){lock(gate){state.dailyShutdownError=ex.Message;state.dailyShutdownOutcome="schedule-error";Save();}}
      if((!state.policiesApplied||(state.websitePolicy!=null&&state.websitePolicy.revision!=appliedPolicyRevision))&&!state.maintenanceBlocked&&Monitor.TryEnter(operationGate)){try{lock(gate){state.activeAction="restore-mode";Save();}ApplyBrowserMode(mode);state.mode=mode;state.policiesApplied=true;state.policyError=null;Save();}catch(Exception ex){state.policyError=ex.Message;state.lastError=ex.Message;Save();Thread.Sleep(1000);}finally{lock(gate){state.activeAction=null;Save();}Monitor.Exit(operationGate);}}

      if(DateTime.UtcNow>=nextLocal){nextLocal=DateTime.UtcNow.AddSeconds(Math.Max(5,cfg.pollSeconds));try{if(string.IsNullOrEmpty(host))host=Discover();if(string.IsNullOrEmpty(host))throw new Exception("Waiting for authenticated local gateway; Servidor control remains independent");Exchange("http://"+host+":"+cfg.gatewayPort+"/agent/",cfg.key,false);misses=0;}catch(Exception ex){state.lastError=ex is WebException?"Local gateway connection unavailable":ex.Message;Save();if(++misses>=3&&string.IsNullOrEmpty(cfg.gatewayHost)){host=null;misses=0;}}}
      if(ChatSupport.Ready)Save();Thread.Sleep(1000);
    }}
    bool DailyShutdownSafe(){var snapshot=Snapshot();return !FreezeSchedule.Active(state.freezeLease)&&!SessionTransitions.Active(state.session)&&!stopping&&!state.maintenanceBlocked&&string.IsNullOrEmpty(state.activeAction)&&snapshot.installation!=null&&snapshot.installation.success==true&&!Util.UpdateBlocksAction(snapshot.update.phase,"shutdown",snapshot.update.requiresStaffReview)&&!state.results.Any(r=>r.state=="shutdown-scheduled");}
    void CheckDailyShutdown(){DateTime now=DateTime.UtcNow;if(!ShutdownSchedule.Due(now,state.dailyShutdownDate)||!Monitor.TryEnter(operationGate))return;try{lock(gate){if(!ShutdownSchedule.Due(now,state.dailyShutdownDate))return;state.dailyShutdownDate=ShutdownSchedule.LocalDate(now);state.dailyShutdownError=null;state.dailyShutdownOutcome=DailyShutdownSafe()?"warning":"deferred-maintenance";Save();if(state.dailyShutdownOutcome!="warning")return;}new Thread(()=>{try{string outcome=ShutdownSchedule.Warn(ShutdownSchedule.WarningSeconds,false,()=>stopping);lock(operationGate){bool powerOff=ShutdownSchedule.ShouldPowerOff(outcome,false,DailyShutdownSafe());lock(gate){state.dailyShutdownOutcome=powerOff?"shutdown-scheduled":outcome;Save();}if(powerOff)ShutdownSchedule.PowerOff(0);}}catch(Exception ex){lock(gate){state.dailyShutdownOutcome="warning-failed";state.dailyShutdownError=ex.Message;Save();}}}){IsBackground=true}.Start();}finally{Monitor.Exit(operationGate);}}
    void ActionLoop(){while(!stopping){Job job=null;lock(gate){if(actions.Count==0){Monitor.Wait(gate,1000);continue;}job=actions.Dequeue();}if(!Util.ValidJob(job)){lock(gate){var expired=state.results.FirstOrDefault(x=>x.id==job.id);if(expired!=null){expired.state="expired";expired.detail="Action expired before execution; no operation performed";expired.utc=Util.Utc();}queuedIds.Remove(job.id);Save();}continue;}lock(operationGate){if(!Util.ValidJob(job)){lock(gate){var expired=state.results.FirstOrDefault(x=>x.id==job.id);if(expired!=null){expired.state="expired";expired.detail="Action expired before execution; no operation performed";expired.utc=Util.Utc();}Save();}}else Execute(job,Snapshot());}lock(gate){queuedIds.Remove(job.id);}}}
    ActionResult RunAction(string action){if(!Util.Allowed(action))throw new Exception("Action is not allowed");string script=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Actions","Invoke-LabAction.ps1");if(!File.Exists(script))throw new Exception("Protected action helper missing");var output=new StringBuilder();var error=new StringBuilder();var info=new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \""+script+"\" -Action "+action){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=new Process{StartInfo=info}){p.OutputDataReceived+=(s,e)=>{if(e.Data!=null)lock(output){if(output.Length<262144)output.AppendLine(e.Data);}};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(error){if(error.Length<4096)error.AppendLine(e.Data);}};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();if(!p.WaitForExit(7200000)){lock(gate){state.maintenanceBlocked=true;state.maintenanceBlockReason="An administrative action exceeded two hours and may still be running. Staff must inspect it locally before any further mutation.";Save();}throw new Exception(state.maintenanceBlockReason);}p.WaitForExit();ActionResult r=null;try{r=Util.From<ActionResult>(output.ToString());}catch{}if(r==null)throw new Exception("Action helper did not return a valid result; inspect protected action logs");if(p.ExitCode!=0||!r.success)throw new Exception(r.detail??"Action helper failed");return r;}}
    void SetFreezeFilter(bool enabled){Util.Run(Path.Combine(Environment.SystemDirectory,"uwfmgr.exe"),"filter "+(enabled?"enable":"disable"),30000);}
    void Execute(Job j,Status before){JobResult result;lock(gate){result=state.results.FirstOrDefault(x=>x.id==j.id);if(result==null){result=new JobResult{id=j.id,action=j.action};state.results.Add(result);}if(!Util.ValidJob(j)){result.state="expired";result.detail="Action expired immediately before execution; no operation performed";result.utc=Util.Utc();Save();return;}state.activeAction=j.action;result.state="running";result.detail="Executing authenticated action";result.utc=Util.Utc();result.bootTicks=before.bootTicks;if(new[]{"class","class-ai","exam","free","unrestrict"}.Contains(j.action)){state.previousPolicyVerified=state.policiesApplied;state.policiesApplied=false;state.policyError="Mode change is running";}if(state.results.Count>1000)state.results.RemoveRange(0,state.results.Count-1000);Save();}try{
      if(state.maintenanceBlocked&&j.action!="status"&&j.action!="uwf-status")throw new Exception(state.maintenanceBlockReason);
      if(FreezeSchedule.Active(state.freezeLease)&&new[]{"thaw-reboot","maintenance-enter","student-return","maintenance","uwf-enable","uwf-disable","uwf-reset-stage1","uwf-reset-stage2","uwf-repair","windows-update"}.Contains(j.action))throw new Exception("Hay un contador de descongelación activo. Use Congelar y Reiniciar primero.");
      if(SessionTransitions.Pending(state.session)&&j.action!="status"&&j.action!="uwf-status")throw new Exception("Hay un cambio de sesion en curso.");
      if(SessionTransitions.Active(state.session)&&new[]{"maintenance","uwf-enable","uwf-reset-stage1","uwf-reset-stage2"}.Contains(j.action))throw new Exception("Use Volver a estudiante para restaurar la proteccion.");
      var updateState=ReadCoordinator();if(Util.UpdateBlocksAction(updateState.phase,j.action,updateState.requiresStaffReview))throw new Exception(updateState.requiresStaffReview?"Automatic update protection or rollback needs staff review; mutations are blocked, status remains available.":"An automatic update is in progress; this action is deferred until its safe phase completes.");
      if(j.action=="status"){result.detail="Status refreshed";}
      else if(j.action=="class"||j.action=="class-ai"||j.action=="exam"||j.action=="free"||j.action=="unrestrict"){string chosen=Util.CanonicalMode(j.action);ApplyBrowserMode(chosen);mode=chosen;state.mode=mode;state.policiesApplied=true;state.policyError=null;result.detail="Student policy, hosts, Edge and Chrome restrictions applied; selected mode persisted";if(chosen!="free")result.detail+=" "+StudentApps.Close(new[]{"RobloxPlayerBeta","RobloxPlayerLauncher"});}
      else if(j.action=="freeze-reboot"||j.action=="thaw-reboot"){if(SessionTransitions.Active(state.session))throw new Exception("Complete Volver a estudiante antes de cambiar la congelación.");FreezeSchedule.RequireDurableState(statePath,before);FreezeSchedule.Begin(state,j,before,Save,SetFreezeFilter,Snapshot,()=>Util.Run(Path.Combine(Environment.SystemDirectory,"shutdown.exe"),"/r /t 60 /c \"UEPLV: cambio de protección solicitado. Guarde su trabajo.\"",10000));return;}
      else if(j.action=="maintenance-enter"||j.action=="student-return"){SessionTransitions.Begin(j.action,j,cfg,state,before,Save);return;}
      else if(j.action=="close-apps"){result.detail=StudentApps.Close();}
      else if(j.action=="cleanup"){string closed=StudentApps.Close();result.detail=closed+" "+RunAction("cleanup").detail;}
      else if(j.action=="maintenance") {if(before.currentServicing==true||before.nextServicing==true)throw new Exception("Servicing already active or scheduled");if(!Util.ProtectionConsistent(before))throw new Exception("Maintenance requires verified current/next UWF filter and C: volume protection");Util.Run(Path.Combine(Environment.SystemDirectory,"uwfmgr.exe"),"servicing enable",30000);var check=Snapshot();if(check.nextServicing!=true)throw new Exception("Servicing was not confirmed for next restart");result.state="awaiting-restart";result.detail="Servicing scheduled; restart in 60 seconds";result.utc=Util.Utc();Save();Util.Run(Path.Combine(Environment.SystemDirectory,"shutdown.exe"),"/r /t 60 /c \"UEPLV: mantenimiento programado\"",10000);return;}
      else if(j.action=="shutdown"){result.state="shutdown-scheduled";result.detail="Apagado programado en 60 segundos.";Save();ShutdownSchedule.PowerOff(60);return;}
      else if(j.action=="shutdown-warning-test"){string outcome=ShutdownSchedule.Warn(20,true,()=>stopping);result.detail=outcome=="cancelled"?"Prueba cancelada con una tecla.":outcome=="no-session"?"No hay una sesión abierta para mostrar el aviso.":"Prueba finalizada sin apagar el equipo.";}
      else if(j.action=="reboot"){result.state="awaiting-restart";result.detail="Restart scheduled in 60 seconds";Save();Util.Run(Path.Combine(Environment.SystemDirectory,"shutdown.exe"),"/r /t 60 /c \"UEPLV: reinicio solicitado por el docente\"",10000);return;}
      else {
        if(j.action=="uwf-reset-stage2"&&(state.resetPhase!="feature-disabled"||before.bootTicks==state.resetBootTicks))throw new Exception("Stage 2 requires successful stage 1 and a subsequent restart");
        if(j.action=="uwf-enable"&&state.resetPhase=="feature-disabled")throw new Exception("Complete reset stage 2 and restart before enabling protection");
        var action=RunAction(j.action);result.detail=action.detail;if(action.resetPhase!=null){state.resetPhase=action.resetPhase;state.resetBootTicks=before.bootTicks;}
        if(action.restartRequired){result.state="awaiting-restart";Save();Util.Run(Path.Combine(Environment.SystemDirectory,"shutdown.exe"),"/r /t 60 /c \"UEPLV: accion administrativa requiere reinicio\"",10000);return;}
        if(action.needsUpdateCheck){result.state="needs-update-check";Save();return;}
      }
      result.state="completed";
    }catch(Exception ex){result.state="failed";result.detail=ex.Message;if((j.action=="maintenance-enter"||j.action=="student-return")&&state.session!=null&&state.session.jobId==j.id)SessionTransitions.Fail(state,ex,Save);if(new[]{"class","class-ai","exam","free","unrestrict"}.Contains(j.action)){state.policiesApplied=false;state.policyError=ex.Message;}}finally{lock(gate){state.activeAction=null;result.utc=Util.Utc();Save();}Interlocked.Increment(ref cloudRevision);}}
    void ApplyBrowserMode(string action){long revision=state.websitePolicy==null?0:state.websitePolicy.revision;RunAction(Util.CanonicalMode(action));if(Util.CanonicalMode(action)!="free")StudentApps.Close(new[]{"Taskmgr"},true);appliedPolicyRevision=revision;}
  }
  sealed class Gateway {
    readonly GatewayConfig cfg;readonly string path;GatewayState state;readonly object gate=new object();volatile bool stopping;HttpListener agents,ui;UdpClient udp;int agentRequests;
    public Gateway(string configPath,string statePath){cfg=Util.From<GatewayConfig>(File.ReadAllText(configPath));path=statePath;state=File.Exists(path)?Util.From<GatewayState>(File.ReadAllText(path)):new GatewayState();}
    public void Stop(){stopping=true;if(agents!=null)agents.Close();if(ui!=null)ui.Close();if(udp!=null)udp.Close();}
    public void Start(){agents=new HttpListener();agents.Prefixes.Add("http://+:"+cfg.agentPort+"/agent/");agents.Start();agents.TimeoutManager.EntityBody=TimeSpan.FromSeconds(10);agents.TimeoutManager.HeaderWait=TimeSpan.FromSeconds(10);agents.TimeoutManager.DrainEntityBody=TimeSpan.FromSeconds(5);ui=new HttpListener();ui.Prefixes.Add("http://127.0.0.1:"+cfg.dashboardPort+"/");ui.Start();udp=new UdpClient(cfg.discoveryPort);new Thread(AgentRequests){IsBackground=true}.Start();new Thread(UiRequests){IsBackground=true}.Start();new Thread(DiscoveryRequests){IsBackground=true}.Start();}
    void Save(){Util.Write(path,state);}
    public Reply Handle(string name,Poll p){lock(gate){var rep=new Reply{requestId=p==null?null:p.requestId,serverUtc=Util.Utc()};if(!cfg.keys.ContainsKey(name)||p==null||p.status==null||p.status.name!=name||!Util.Fresh(p.sentUtc,120)||string.IsNullOrEmpty(p.deviceId)||p.sequence<1){rep.error="Invalid enrollment request";return rep;}Device d;if(state.devices.TryGetValue(name,out d)){if(d.deviceId!=p.deviceId||p.sequence<=d.sequence){rep.error="Device identity conflict or replay";return rep;}}else{d=new Device{name=name,deviceId=p.deviceId,enrolledUtc=Util.Utc()};state.devices[name]=d;}d.sequence=p.sequence;d.lastSeenUtc=Util.Utc();d.status=p.status;if(p.results!=null)d.results=p.results.TakeLastCompat(1000).ToList();d.jobs.RemoveAll(x=>!Util.ValidJob(x)||d.results.Any(r=>r.id==x.id));rep.accepted=true;rep.jobs=d.jobs.ToList();Save();return rep;}}
    public bool Queue(string name,string action){lock(gate){Device d;if(!state.devices.TryGetValue(name,out d)||!Util.Allowed(action))return false;if(d.jobs.Any(x=>x.action==action&&Util.ValidJob(x)))return false;d.jobs.Add(new Job{id=Guid.NewGuid().ToString(),action=action,issuedUtc=Util.Utc(),expiresUtc=DateTime.UtcNow.AddMinutes(5).ToString("o")});Save();return true;}}
    static string Read(HttpListenerRequest req){if(req.ContentLength64>131072)throw new Exception("Request too large");using(var r=new StreamReader(req.InputStream,Encoding.UTF8)){var b=new char[131073];int n=0,c;while(n<b.Length&&(c=r.Read(b,n,b.Length-n))>0)n+=c;if(n>131072)throw new Exception("Request too large");return new string(b,0,n);}}
    static void Send(HttpListenerResponse res,int code,string body,string type){res.StatusCode=code;res.ContentType=type;res.Headers["Cache-Control"]="no-store";res.Headers["X-Content-Type-Options"]="nosniff";var b=Encoding.UTF8.GetBytes(body);res.ContentLength64=b.Length;res.OutputStream.Write(b,0,b.Length);res.Close();}
    void AgentRequests(){while(!stopping){try{var c=agents.GetContext();if(Interlocked.Increment(ref agentRequests)>16){Interlocked.Decrement(ref agentRequests);Send(c.Response,503,"{}","application/json");continue;}ThreadPool.QueueUserWorkItem(delegate{try{ProcessAgentRequest(c);}finally{Interlocked.Decrement(ref agentRequests);}});}catch{}}}
    void ProcessAgentRequest(HttpListenerContext c){try{if(c.Request.HttpMethod!="POST"){Send(c.Response,405,"{}","application/json");return;}var raw=Read(c.Request);var e=Util.From<Envelope>(raw);string k;if(e==null||!cfg.keys.TryGetValue(e.name,out k)){Send(c.Response,403,"{}","application/json");return;}var p=Util.From<Poll>(Util.Unprotect(e.name,k,raw));var rep=Handle(e.name,p);Send(c.Response,200,Util.Protect(e.name,k,Util.Json(rep)),"application/json");}catch{try{Send(c.Response,403,"{}","application/json");}catch{}}}
    void DiscoveryRequests(){while(!stopping){try{var remote=new IPEndPoint(IPAddress.Any,0);var bytes=udp.Receive(ref remote);if(bytes.Length>4096)continue;var d=Util.From<Discovery>(Encoding.UTF8.GetString(bytes));if(d==null||!cfg.keys.ContainsKey(d.name)||string.IsNullOrEmpty(d.nonce)||d.nonce.Length>80)continue;d.port=cfg.agentPort;d.signature=Convert.ToBase64String(Util.Sign(cfg.discoveryPrivateKey,d.name+"\n"+d.nonce+"\n"+d.port));var b=Encoding.UTF8.GetBytes(Util.Json(d));udp.Send(b,b.Length,remote);}catch{}}}
    void UiRequests(){while(!stopping){HttpListenerContext c=null;try{c=ui.GetContext();if(!IPAddress.IsLoopback(c.Request.RemoteEndPoint.Address)){Send(c.Response,403,"{}","application/json");continue;}var route=c.Request.Url.AbsolutePath;if(route=="/"&&c.Request.HttpMethod=="GET"){Send(c.Response,200,Dashboard,"text/html; charset=utf-8");continue;}
      string token=c.Request.Headers["X-Admin-Token"]??"";if(!Util.Equal(Encoding.UTF8.GetBytes(token),Encoding.UTF8.GetBytes(cfg.dashboardToken))){Send(c.Response,403,"{}","application/json");continue;}string origin=c.Request.Headers["Origin"];if(origin!=null&&origin!="http://127.0.0.1:"+cfg.dashboardPort){Send(c.Response,403,"{}","application/json");continue;}
      if(route=="/api/devices"&&c.Request.HttpMethod=="GET"){lock(gate)Send(c.Response,200,Util.Json(new{devices=state.devices.Values.OrderBy(x=>x.name).ToList(),expected=cfg.keys.Keys.OrderBy(x=>x).ToList()}),"application/json");}
      else if(route=="/api/job"&&c.Request.HttpMethod=="POST"){var d=Util.From<Dictionary<string,string>>(Read(c.Request));bool queued=Queue(d["name"],d["action"]);Send(c.Response,queued?200:409,Util.Json(new{queued=queued}),"application/json");}
      else Send(c.Response,404,"{}","application/json");
    }catch{if(c!=null)try{Send(c.Response,400,"{}","application/json");}catch{}}}}
    const string Dashboard=@"<!doctype html><html lang='es'><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>UEPLV · Administración del laboratorio</title><style>body{margin:0;background:#151311;color:#f5f0e8;font:15px system-ui}main{max-width:1450px;margin:auto;padding:30px}h1{font-size:28px}button,select{background:#3e3020;color:white;border:1px solid #9b7244;padding:8px;border-radius:6px;cursor:pointer}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid #443529;vertical-align:top}small{color:#bbb}#notice{color:#ffd893}pre{white-space:pre-wrap;font-size:12px}details{max-width:440px}.ok{color:#a9ddb6}.off{color:#f5b7a7}</style><main><h1>UEPLV · Administración del laboratorio</h1><p>Control local complementario de Veyon. Los cambios se confirman por cada equipo.</p><p id='notice'>Conectando…</p><table><thead><tr><th>Equipo</th><th>Conexión</th><th>UWF actual / próximo</th><th>Overlay</th><th>Acciones</th><th>Resultados</th></tr></thead><tbody id='rows'></tbody></table></main><script>
let token=location.hash.slice(1)||sessionStorage.getItem('ueplvToken');if(token){sessionStorage.setItem('ueplvToken',token);history.replaceState(null,'',location.pathname)}
const esc=s=>String(s??'').replace(/[&<>""']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','""':'&quot;',""'"":'&#39;'}[c]));
const enabled=x=>x===true?'ON':x===false?'OFF':'?';
async function call(p,body){let r=await fetch(p,{method:body?'POST':'GET',headers:{'X-Admin-Token':token||'','Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(r.status===403?'Abre el panel con el acceso de MAINTENANCE.':'Solicitud no aceptada ('+r.status+').');return r.json()}
async function job(name,action){const warnings={reboot:'Reiniciar el equipo',maintenance:'Iniciar mantenimiento UWF y reiniciar','close-apps':'Cerrar las aplicaciones del estudiante; se puede perder trabajo sin guardar',cleanup:'Eliminar archivos personales, historial y papelera SOLO del estudiante; esta acción es destructiva','uwf-disable':'Desactivar protección UWF y reiniciar','uwf-reset-stage1':'Desinstalar UWF y reiniciar (etapa 1)','uwf-reset-stage2':'Reinstalar UWF y reiniciar (etapa 2)','uwf-purge-swap':'Eliminar solamente el swap UWF inactivo'};if(warnings[action]&&!confirm(warnings[action]+' — '+name+'\nEl trabajo vence en cinco minutos.'))return;try{await call('/api/job',{name,action});await refresh()}catch(e){alert(e.message)}}
async function refresh(){try{let d=await call('/api/devices');document.getElementById('notice').textContent=d.devices.length+' de '+d.expected.length+' equipos registrados. Las acciones requieren el equipo conectado.';document.getElementById('rows').innerHTML=d.expected.map(name=>{let x=d.devices.find(q=>q.name===name);if(!x)return '<tr><td>'+esc(name)+'</td><td colspan=5>Esperando instalación y registro</td></tr>';let s=x.status||{},online=Date.now()-Date.parse(x.lastSeenUtc)<60000;return '<tr><td>'+esc(name)+'<br><small>'+esc(s.mode)+(s.modeApplied?'':' (pendiente)')+' · '+esc((s.installation||{}).stage)+'</small><br><small>'+esc((s.installation||{}).detail)+'</small></td><td class='+ (online?'ok':'off')+'>'+(online?'Conectado':'Sin conexión')+'<br><small>'+esc(x.lastSeenUtc)+'</small></td><td>'+enabled(s.currentEnabled)+' / '+enabled(s.nextEnabled)+'<br><small>C: '+enabled(s.currentCProtected)+' / '+enabled(s.nextCProtected)+'<br>'+(s.currentServicing||s.nextServicing?'Mantenimiento programado/activo':'')+esc(s.uwfError)+'</small></td><td>'+esc(s.overlayMB)+' MB usados<br><small>'+esc(s.availableMB)+' MB disponibles</small><br><small class=off>'+((s.overlayCriticalMB&&s.overlayMB>=s.overlayCriticalMB)?'CRÍTICO: guardar trabajo y coordinar reinicio':(s.overlayWarningMB&&s.overlayMB>=s.overlayWarningMB)?'AVISO: overlay cerca del límite':'')+'</small></td><td><select id=""a-'+name+'""><option value=status>Actualizar estado</option><option value=class>Modo clase</option><option value=exam>Modo examen</option><option value=class-ai>Clase sin AI</option><option value=free>Modo libre</option><option value=close-apps>Cerrar aplicaciones del estudiante</option><option value=cleanup>Limpiar archivos e historial del estudiante</option><option value=uwf-status>Estado UWF</option><option value=uwf-enable>Activar UWF verificado</option><option value=uwf-disable>Desactivar UWF</option><option value=uwf-purge-swap>Purgar swap UWF inactivo</option><option value=uwf-repair>Reparar Windows/UWF</option><option value=uwf-reset-stage1>Reset UWF etapa 1</option><option value=uwf-reset-stage2>Reset UWF etapa 2</option><option value=windows-update>Actualizar Windows sin UWF</option><option value=reboot>Reiniciar</option><option value=maintenance>Mantenimiento UWF</option></select> <button '+(!online?'disabled':'')+' onclick=""job(\''+name+'\',document.getElementById(\'a-'+name+'\').value)"">Enviar</button></td><td><details><summary>'+x.jobs.length+' pendientes · '+x.results.length+' resultados</summary><pre>'+esc(JSON.stringify({pendientes:x.jobs,resultados:x.results.slice(-10)},null,2))+'</pre></details></td></tr>'}).join('')}catch(e){document.getElementById('notice').textContent=e.message}}
refresh();setInterval(refresh,5000);</script></html>";
  }
  static class Compat { public static IEnumerable<T> TakeLastCompat<T>(this IEnumerable<T> source,int count){return source.Skip(Math.Max(0,source.Count()-count));} }
  sealed class LabService:ServiceBase {
    readonly bool gateway;Thread worker;Agent agent;Gateway server;
    public LabService(bool gateway){this.gateway=gateway;ServiceName=gateway?"UEPLVGateway":"UEPLVAgent";CanStop=true;AutoLog=true;}
    protected override void OnStart(string[] args){string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"UEPLV","Management");if(gateway){server=new Gateway(Path.Combine(root,"gateway-config.json"),Path.Combine(root,"gateway-state.json"));server.Start();}else{agent=new Agent(Path.Combine(root,"agent-config.json"),Path.Combine(root,"agent-state.json"));worker=new Thread(agent.Loop){IsBackground=true};worker.Start();ChatSupport.Start();}}
    protected override void OnStop(){ChatSupport.Stop();if(agent!=null)agent.Stop();if(server!=null)server.Stop();if(worker!=null)worker.Join(5000);}
  }
