    static int SelfTest(){string temp=Path.Combine(Path.GetTempPath(),"UEPLV-selftest-"+Guid.NewGuid());Directory.CreateDirectory(temp);try{string key=Util.Token(64);Assert((int)ServicePointManager.SecurityProtocol==0,"HTTPS uses Windows secure TLS defaults");Assert(typeof(Program).Assembly.GetCustomAttributes(typeof(System.Runtime.Versioning.TargetFrameworkAttribute),false).Cast<System.Runtime.Versioning.TargetFrameworkAttribute>().Single().FrameworkName==".NETFramework,Version=v4.8","executable targets modern .NET TLS behavior");string p=Util.Protect("UEPLV-01",key,"hello");Assert(Util.Unprotect("UEPLV-01",key,p)=="hello","encrypted authenticated round trip");var e=Util.From<Envelope>(p);e.data=e.data.Substring(0,e.data.Length-4)+"AAAA";bool denied=false;try{Util.Unprotect("UEPLV-01",key,Util.Json(e));}catch{denied=true;}Assert(denied,"ciphertext modification rejected");denied=false;try{Util.Unprotect("UEPLV-02",key,p);}catch{denied=true;}Assert(denied,"wrong device rejected");denied=false;try{Util.Unprotect("UEPLV-01",Util.Token(64),p);}catch{denied=true;}Assert(denied,"wrong credential rejected");
